def rot(line,m1,m2):
    B=line/2; mu=m1*m2/(m1+m2)*amu; I=h/(8*math.pi**2*c*B); return B,I,math.sqrt(I/mu)*1e10
def sho(k,m1,m2):
    mu=m1*m2/(m1+m2)*amu; return math.sqrt(k/mu)/(2*math.pi*c)
